    {
      "speaker": "A",
      "text": "そうだなあ。昨日、映画を見たんだ。面白かったよ。",
      "english": "Let me see. I saw a movie yesterday. It was interesting.",
      "intendedTargetIds": []
    },
    {
      "speaker": "B",
      "text": "へえ、本当？",
      "english": "Oh, really?",
      "intendedTargetIds": []
    },
    {
      "speaker": "A",
      "text": "うん。また行きたいな。",
      "english": "Yeah. I want to go again.",
      "intendedTargetIds": []
    }
  ],
  "sceneId": "LS1",
  "setting": "A park bench"
}

